/// `maps.find((m) => m.type === mapType)` (`TribeNames.ts:22-25`).
pub fn map_info(map_type: &str) -> Option<&'static MapInfo> {
    MAPS.iter().find(|m| m.map_type == map_type)
}

/// `Object.values(GameMapType).includes(name)`: is `name` a known map wire name?
pub fn is_game_map_type(name: &str) -> bool {
    GAME_MAP_TYPES.iter().any(|(_, v)| *v == name)
}
